1	package docker
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"maps"
9		"net/netip"
10		"slices"
11		"strings"
12	
13		"github.com/anthnel/devdesk/internal/engine"
14	)
15	
16	// ContainerNetworking is the narrow, read-only view of a container's network
17	// attachment that the Path tab needs.
18	type ContainerNetworking struct {
19		Name     string // engine's name without the leading "/"; untrusted text
20		Running  bool
21		Mode     string // HostConfig.NetworkMode
22		Networks []EndpointNetwork
23	}
24	
25	// EndpointNetwork is one network a container is attached to.
26	type EndpointNetwork struct {
27		Name       string
28		IPv4       netip.Addr
29		Gateway    netip.Addr
30		GwPriority *int
31	}
32	
33	// ErrDockerOnly is returned for reads only Docker Engine answers.
34	var ErrDockerOnly = errors.New("only Docker Engine answers this read")
35	
36	const containerNetworkingFormat = `{"Name":{{json .Name}},"Mode":{{json .HostConfig.NetworkMode}},"Running":{{json .State.Running}},"Networks":{{json .NetworkSettings.Networks}}}`
37	
38	const maxInspectBytes = 256 << 10
39	
40	// requireDockerEngine refuses reads only Docker Engine answers, before any
41	// invocation: Podman's inspect and info shapes differ.
42	func requireDockerEngine() error {
43		if engine.Current().Name != engine.Docker {
44			return ErrDockerOnly
45		}
46		return requireEngine()
47	}
48	
49	// InspectContainerNetworking reads one container's network attachment with
50	// `container inspect --format`, which selects no Env, Labels or Mounts. It
51	// never starts the container and its error carries no command output.
52	func InspectContainerNetworking(ctx context.Context, id string) (ContainerNetworking, error) {
53		if !IsContainerID(id) {
54			return ContainerNetworking{}, fmt.Errorf("invalid container id %q", id)
55		}
56		if err := requireDockerEngine(); err != nil {
57			return ContainerNetworking{}, err
58		}
59		out, err := runner.Run(dockerCmd{
60			Args: []string{"container", "inspect", "--format", containerNetworkingFormat, id},
61			Ctx:  ctx,
62		})
63		if err != nil {
64			return ContainerNetworking{}, wrapErr(cmdLabel("container inspect"), err)
65		}
66		return parseContainerNetworking(out)
67	}
68	
69	// parseContainerNetworking decodes the output of containerNetworkingFormat.
70	// Addresses that are not IPv4 become the zero Addr; networks are sorted by name.
71	func parseContainerNetworking(out []byte) (ContainerNetworking, error) {
72		if len(out) > maxInspectBytes {
73			return ContainerNetworking{}, fmt.Errorf("container inspect output exceeds %d bytes", maxInspectBytes)
74		}
75		var raw struct {
76			Name     string
77			Mode     string
78			Running  bool
79			Networks map[string]struct {
80				IPAddress  string
81				Gateway    string
82				GwPriority *int
83			}
84		}
85		if err := json.Unmarshal(out, &raw); err != nil {
86			return ContainerNetworking{}, fmt.Errorf("parse container inspect output: %w", err)
87		}
88		n := ContainerNetworking{
89			Name:    strings.TrimPrefix(raw.Name, "/"),
90			Running: raw.Running,
91			Mode:    raw.Mode,
92		}
93		for _, name := range slices.Sorted(maps.Keys(raw.Networks)) {
94			e := raw.Networks[name]
95			n.Networks = append(n.Networks, EndpointNetwork{
96				Name:       name,
97				IPv4:       parseIPv4(e.IPAddress),
98				Gateway:    parseIPv4(e.Gateway),
99				GwPriority: e.GwPriority,
100			})
101		}
102		return n, nil
103	}
104	
105	// parseIPv4 returns the address when s is a valid IPv4 one, else the zero Addr.
106	func parseIPv4(s string) netip.Addr {
107		a, err := netip.ParseAddr(s)
108		if err != nil || !a.Is4() {
109			return netip.Addr{}
110		}
111		return a
112	}
113	
114	// ListContainersContext is ListContainers with a context that kills the
115	// invocation when cancelled.
116	func ListContainersContext(ctx context.Context, all bool) ([]Container, error) {
117		if err := requireEngine(); err != nil {
118			return nil, err
119		}
120	
121		args := []string{"ps"}
122		if all {
123			args = append(args, "--all")
124		}
125		args = append(args, "--format", templates().PS)
126	
127		output, err := runner.Run(dockerCmd{Args: args, Ctx: ctx})
128		if err != nil {
129			return nil, wrapErr(cmdLabel("ps"), err)
130		}
131		return parseContainers(output), nil
132	}
133	
134	// EngineOperatingSystem returns the engine's operating system text as printed,
135	// trimmed but not sanitized: the caller treats it as untrusted.
136	func EngineOperatingSystem(ctx context.Context) (string, error) {
137		if err := requireDockerEngine(); err != nil {
138			return "", err
139		}
140		out, err := runner.Run(dockerCmd{Args: []string{"info", "--format", "{{.OperatingSystem}}"}, Ctx: ctx})
141		if err != nil {
142			return "", wrapErr(cmdLabel("info"), err)
143		}
144		return strings.TrimSpace(string(out)), nil
145	}
